// ../case-tool/src/services/action-schema-api.ts
async function getActionSchema(params) {
  const loginStatus = await getLoginStatusAsync();
  if (loginStatus.loginStatus !== "Logged in" || !loginStatus.baseUrl || !loginStatus.organizationId || !loginStatus.tenantId || !loginStatus.accessToken) {
    throw new Error("Not logged in. Run 'uip login' first.");
  }
  const query = new URLSearchParams({
    appSystemName: params.systemName,
    version: String(params.deployVersion)
  });
  const url = `${loginStatus.baseUrl}/${loginStatus.organizationId}/apps_/default/api/v1/default/action-schema?${query}`;
  const response = await fetch(url, {
    method: "GET",
    headers: {
      Authorization: `Bearer ${loginStatus.accessToken}`,
      "Content-Type": "application/json",
      "X-Uipath-Tenantid": loginStatus.tenantId,
      Accept: "application/json"
    }
  });
  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Action schema request failed: ${response.status} ${response.statusText} - ${errorText}`);
  }
  return await response.json();
}

// ../case-tool/src/services/entry-point-api.ts
async function getEntryPointDetails(params) {
  const loginStatus = await getLoginStatusAsync();
  if (loginStatus.loginStatus !== "Logged in" || !loginStatus.baseUrl || !loginStatus.organizationId || !loginStatus.tenantName || !loginStatus.tenantId || !loginStatus.accessToken) {
    throw new Error("Not logged in. Run 'uip login' first.");
  }
  const key = `${encodeURIComponent(params.processKey)}:${encodeURIComponent(params.processVersion)}`;
  const path = `/odata/Processes/UiPath.Server.Configuration.OData.GetPackageEntryPointsV2(key='${key}')`;
  const query = new URLSearchParams({ feedId: params.feedId });
  const url = `${loginStatus.baseUrl}/${loginStatus.organizationId}/${loginStatus.tenantName}/orchestrator_${path}?${query}`;
  const headers = {
    Authorization: `Bearer ${loginStatus.accessToken}`,
    "Content-Type": "application/json",
    "X-Uipath-Tenantid": loginStatus.tenantId,
    Accept: "application/json"
  };
  if (params.folderKey) {
    headers["x-uipath-folderkey"] = params.folderKey;
  }
  const response = await fetch(url, {
    method: "GET",
    headers
  });
  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Entry point details request failed: ${response.status} ${response.statusText} - ${errorText}`);
  }
  const data = await response.json();
  return data.value;
}

