// ../case-tool/src/services/enrichment-service.ts
var TASK_TYPE_TO_INDEX = {
  process: "processOrchestration",
  agent: "agent",
  rpa: "process",
  "api-workflow": "api",
  "case-management": "caseManagement",
  action: "action-apps",
  "flow-process": "flow"
};
function findProcessEntry(entries, id) {
  return entries.find((e) => e.entityKey === id);
}
function findActionAppEntry(entries, id) {
  return entries.find((e) => e.id === id);
}
function findCustomDataValue(parsed, name) {
  const key = Object.keys(parsed).find((candidate) => candidate.toLowerCase() === name.toLowerCase());
  return key === undefined ? undefined : parsed[key];
}
function parseCustomData(raw) {
  const [parseError, parsed] = catchError(() => JSON.parse(raw));
  if (parseError) {
    throw new Error(`Failed to parse customData: ${parseError.message}`);
  }
  const customData = {
    ProcessKey: findCustomDataValue(parsed, "ProcessKey"),
    ProcessVersion: findCustomDataValue(parsed, "ProcessVersion"),
    FeedId: findCustomDataValue(parsed, "FeedId")
  };
  if (!customData.ProcessKey || !customData.ProcessVersion || !customData.FeedId) {
    throw new Error("customData is missing required fields: ProcessKey, ProcessVersion, FeedId" + ` (found: ${Object.keys(parsed).join(", ") || "no keys"})`);
  }
  return customData;
}
async function enrichProcessType(taskType, id) {
  const indexType = TASK_TYPE_TO_INDEX[taskType];
  const entries = await loadResourceIndex(indexType);
  const entry = findProcessEntry(entries, id);
  if (!entry) {
    throw new Error(`No ${taskType} entry found with entityKey "${id}" in ${indexType}-index.json`);
  }
  const customData = parseCustomData(entry.customData);
  const folderKey = entry.folders?.[0]?.key;
  const params = {
    processKey: customData.ProcessKey,
    processVersion: customData.ProcessVersion,
    feedId: customData.FeedId,
    ...folderKey ? { folderKey } : {}
  };
  const entryPoints = await getEntryPointDetails(params);
  if (entryPoints.length === 0) {
    throw new Error(`No entry points returned for ${taskType} "${entry.name}" (key: ${customData.ProcessKey})`);
  }
  const ep = entryPoints[0];
  const inputs = transformSchemaToVariables(ep.InputArguments, {
    includeRequired: true
  });
  const outputs = transformSchemaToVariables(ep.OutputArguments);
  return {
    name: entry.name,
    type: taskType,
    folderPath: entry.folders?.[0]?.fullyQualifiedName ?? "",
    inputs,
    outputs
  };
}
async function enrichActionType(id) {
  const entries = await loadResourceIndex("action-apps");
  const entry = findActionAppEntry(entries, id);
  if (!entry) {
    throw new Error(`No action entry found with id "${id}" in action-apps-index.json`);
  }
  const params = {
    systemName: entry.systemName,
    deployVersion: entry.deployVersion
  };
  const schema = await getActionSchema(params);
  const inputVars = {
    ...convertActionArgsToVariables(schema.inputs),
    ...convertActionArgsToVariables(schema.inOuts)
  };
  const outputVars = {
    ...convertActionArgsToVariables(schema.outputs),
    ...convertActionArgsToVariables(schema.inOuts)
  };
  const outcomeVars = convertActionArgsToVariables(schema.outcomes);
  const outcomeKeys = Object.keys(outcomeVars);
  const actionType = outcomeKeys.length > 0 ? outcomeVars[outcomeKeys[0]].type : "string";
  outputVars.Action = outcomeKeys.length > 0 ? {
    type: actionType,
    options: outcomeKeys.map((k) => ({ value: k, label: k }))
  } : { type: actionType };
  outputVars.hitlTask = HITL_TASK_OUTPUT_VARIABLE;
  return {
    name: entry.deploymentTitle,
    type: "action",
    folderPath: entry.deploymentFolder?.fullyQualifiedName ?? "",
    inputs: inputVars,
    outputs: outputVars
  };
}
async function enrichTask(taskType, id, options) {
  const result = taskType === "action" ? await enrichActionType(id) : await enrichProcessType(taskType, id);
  const inputsList = mapEntryPointVariablesToInputOutput(result.inputs, false);
  let outputsList = mapEntryPointVariablesToInputOutput(result.outputs, true);
  if (taskType === "case-management") {
    outputsList = [];
  } else {
    outputsList.push(buildErrorOutput());
  }
  const { inputsWithVars, outputsWithVars } = addVarIdsToInputsOutputs({
    inputs: inputsList,
    outputs: outputsList,
    elementId: options?.elementId ?? ""
  });
  return {
    name: result.name,
    type: result.type,
    folderPath: result.folderPath,
    inputs: inputsWithVars,
    outputs: outputsWithVars
  };
}
export {
  enrichTask,
  parseCustomData
};

